"""Webhook signature verification tests.

Pins cross-language byte-equivalence with:
  - Rust signer: the Nanorix API service
  - Go verifier: tools/nanorix-webhook-verify-go/verifier.go
  - TypeScript verifier: the TypeScript SDK

If any implementation drifts on the HMAC wire form ('{ts}.{body}' + sha256=
prefix + lowercase hex), this test fails.

 Forever-Standard: wire form is permanent.
"""
from __future__ import annotations

import hashlib
import hmac
import time


from nanorix.resources.webhooks import Webhook


# Cross-language fixture: generated by Go signer
# (tools/nanorix-webhook-verify-go) on 2026-05-11. Pinned here so that
# the Python verifier MUST accept it. If Python drifts, this test fails.
FIXTURE_BODY = (
    b'{"event":"capsule.created","capsule_id":"cap_123",'
    b'"at":"2026-05-11T00:00:00Z"}'
)
FIXTURE_SECRET = "whsec_fixture_pin_2026"
FIXTURE_TIMESTAMP = 1_715_000_000
FIXTURE_SIGNATURE = (
    "sha256=2675fe0d4fd177bc35bcaa489e35c96c8f714031e49f79004e727111ec1e7777"
)


def _sign(body: bytes, secret: str, timestamp: int) -> str:
    """Reference signer (parity with the Nanorix API service signing path)."""
    message = f"{timestamp}.".encode("utf-8") + body
    mac = hmac.new(secret.encode("utf-8"), message, hashlib.sha256).hexdigest()
    return f"sha256={mac}"


# ── Cross-language byte-equivalence ───────────────────────────────


def test_cross_language_fixture_from_go_is_verified():
    """The Go signer's output must verify in Python (byte-equivalence)."""
    # Inject a Python "now()" close to the fixture timestamp so replay
    # protection does not reject the (intentionally stable) fixture.
    # We override time.time for this single test via the underlying
    # implementation that uses time.time().
    import time as time_mod

    real_time = time_mod.time
    try:
        time_mod.time = lambda: float(FIXTURE_TIMESTAMP)
        assert Webhook.verify_signature(
            payload=FIXTURE_BODY,
            signature=FIXTURE_SIGNATURE,
            secret=FIXTURE_SECRET,
            timestamp=FIXTURE_TIMESTAMP,
        )
    finally:
        time_mod.time = real_time


def test_python_signer_matches_fixture():
    """Python signer over the same inputs MUST produce the Go fixture."""
    computed = _sign(FIXTURE_BODY, FIXTURE_SECRET, FIXTURE_TIMESTAMP)
    assert computed == FIXTURE_SIGNATURE, (
        f"Python signer drifted from Go fixture; got {computed}"
    )


# ── Round-trip ───────────────────────────────────────────────────


def test_round_trip_valid_signature():
    body = b'{"event":"capsule.created","capsule_id":"cap_x"}'
    secret = "whsec_test"
    ts = int(time.time())
    sig = _sign(body, secret, ts)

    assert Webhook.verify_signature(
        payload=body,
        signature=sig,
        secret=secret,
        timestamp=ts,
    )


def test_rejects_tampered_body():
    body = b'{"event":"capsule.created","capsule_id":"cap_x"}'
    secret = "whsec_test"
    ts = int(time.time())
    sig = _sign(body, secret, ts)

    tampered = b'{"event":"capsule.created","capsule_id":"cap_TAMPERED"}'
    assert not Webhook.verify_signature(
        payload=tampered,
        signature=sig,
        secret=secret,
        timestamp=ts,
    )


def test_rejects_wrong_secret():
    body = b'{}'
    ts = int(time.time())
    sig = _sign(body, "whsec_real", ts)

    assert not Webhook.verify_signature(
        payload=body,
        signature=sig,
        secret="whsec_wrong",
        timestamp=ts,
    )


def test_rejects_missing_prefix():
    body = b'{}'
    secret = "whsec_test"
    ts = int(time.time())
    sig = _sign(body, secret, ts)
    corrupted = sig[len("sha256="):]  # strip prefix

    assert not Webhook.verify_signature(
        payload=body,
        signature=corrupted,
        secret=secret,
        timestamp=ts,
    )


def test_rejects_stale_timestamp():
    body = b'{}'
    secret = "whsec_test"
    stale_ts = int(time.time()) - 600  # 10 minutes ago
    sig = _sign(body, secret, stale_ts)

    assert not Webhook.verify_signature(
        payload=body,
        signature=sig,
        secret=secret,
        timestamp=stale_ts,
    )


def test_rejects_future_timestamp():
    body = b'{}'
    secret = "whsec_test"
    future_ts = int(time.time()) + 600
    sig = _sign(body, secret, future_ts)

    assert not Webhook.verify_signature(
        payload=body,
        signature=sig,
        secret=secret,
        timestamp=future_ts,
    )


def test_accepts_signature_within_replay_window():
    body = b'{}'
    secret = "whsec_test"
    ts = int(time.time()) - 60  # 1 minute ago, well within 5-min window
    sig = _sign(body, secret, ts)

    assert Webhook.verify_signature(
        payload=body,
        signature=sig,
        secret=secret,
        timestamp=ts,
    )


def test_empty_body_signed_and_verified():
    body = b""
    secret = "whsec_empty"
    ts = int(time.time())
    sig = _sign(body, secret, ts)

    assert Webhook.verify_signature(
        payload=body,
        signature=sig,
        secret=secret,
        timestamp=ts,
    )


def test_lowercase_hex_only():
    """All implementations emit lowercase hex per Forever-Standard."""
    body = b'{}'
    secret = "whsec_test"
    ts = 1_715_000_000
    sig = _sign(body, secret, ts)
    hex_part = sig[len("sha256="):]
    assert hex_part == hex_part.lower(), f"signature must be lowercase: {sig}"


def test_signature_changes_with_timestamp():
    body = b'{}'
    secret = "whsec_test"
    sig1 = _sign(body, secret, 1_715_000_000)
    sig2 = _sign(body, secret, 1_715_000_001)
    assert sig1 != sig2


def test_signature_changes_with_body():
    secret = "whsec_test"
    ts = 1_715_000_000
    sig_a = _sign(b'a', secret, ts)
    sig_b = _sign(b'b', secret, ts)
    assert sig_a != sig_b
